let colors = ['#DE183C', '#F2B541', '#0C79BB', '#2DACB2', '#E46424', '#f293af', '#19446B'];

let ctx;
let centerX, centerY;
let shapes = [];
let lines = [];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;

	let gridArea = width * 0.9;
	let cellCount = 6;
	let cellSize = gridArea / cellCount;
	let w = cellSize * 0.8;
	for (let row = 0; row < cellCount; row++) {
		let y = row * cellSize + cellSize / 2 + (height - gridArea) / 2;
		lines.push({ x1: 0, y1: y + w/2, x2: width, y2: y+w/2});
		for (let col = 0; col < cellCount; col++) {
			let x = col * cellSize + cellSize / 2 + (width - gridArea) / 2;
			shapes.push(new Flower(x, y, w));
		}
	}
}

function draw() {
  // === Variant 1: Neon Kinetic Glitch Modification ===
  dynamicShift = sin((frameCount * speedMult) * 0.08) * 40;

	background('#f4f0e6');
	for (let s of shapes) {
		s.run();
	}
	for (let l of lines) {
		line(l.x1, l.y1, l.x2, l.y2);
	}
}

function easeInOutCubic(x) {
	return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

function easeOutQuart(x) {
	return 1 - Math.pow(1 - x, 4);
}

function drawLeaf(x, y, w, t) {
	push();
	translate(x, y);
	scale(t, 1);
	beginShape();
	for (let a = 0; a < HALF_PI; a += TAU / 360) {
		vertex(-(w / 2) + w * cos(a), -(w / 2) + w * sin(a));
	}
	for (let a = PI; a < PI + HALF_PI; a += TAU / 360) {
		vertex((w / 2) + w * cos(a), (w / 2) + w * sin(a));
	}
	endShape();
	pop();
}

class Flower {
	constructor(x, y, w) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.animationDuration = 60;
		this.initialize();
		shuffle(colors, true);
		this.clr1 = colors[0];
		this.clr2 = colors[1];
		this.clr3 = colors[2];
		this.eyes = new Eye(0, 0, this.w / 3);
	}

	show() {
		push();
		translate(this.x, this.y);
		noStroke();
		stroke('#000000');
		strokeWeight(width / 900);
		push();
		translate(0, this.w / 2);
		rotate(this.flowerSwayAngle);
		translate(0, -(this.w / 3 / 2) - (this.w / 2));
		push();
		rotate(this.petalRotation);
		fill(this.clr1);
		for (let i = 0; i < 4; i++) {
			circle(this.w / 3 / 2, this.w / 3 / 2, this.w / 3);
			rotate(TAU / 4);
		}
		pop();
		fill(this.clr2);
		circle(0, 0, this.w / 3);
		this.eyes.run();
		pop();
		push();
		translate(0, this.w / 2);
		fill(this.clr3);
		push();
		rotate(-this.leafAngle);
		drawLeaf(this.w / 3 / 2, -this.w / 3 / 2, this.w / 3, 1);
		pop();
		rotate(this.leafAngle);
		drawLeaf(-this.w / 3 / 2, -this.w / 3 / 2, this.w / 3, -1);
		pop();
		pop();
	}

	move() {
		this.timer++;
		if (0 < this.timer && this.timer < this.animationDuration) {
			let normalizedTime = norm(this.timer, 0, this.animationDuration - 1);
			if (this.animationType === 0) {
				this.leafAngle = lerp(0, this.leafSwayAmplitude, sin(easeInOutCubic(normalizedTime) * TAU));
			} else if (this.animationType === 1) {
				this.petalRotation = lerp(0, this.petalDirection, easeInOutCubic(normalizedTime));
			} else if (this.animationType === 2) {
				this.flowerSwayAngle = lerp(0, this.flowerSwayAmplitude, sin(easeInOutCubic(normalizedTime) * TAU));
			}
		}
		if (this.animationDuration < this.timer) {
			this.initialize();
		}
	}

	initialize() {
		this.leafAngle = 0;
		this.leafSwayAmplitude = PI / 20;
		this.petalRotation = 0;
		this.petalDirection = PI * random([-1, 1]);
		this.flowerSwayAngle = 0;
		this.flowerSwayAmplitude = PI * 0.03 * random([-1, 1]);
		this.animationType = int(random(3));
		this.timer = -int(random(400));
	}

	run() {
		this.show();
		this.move();
	}
}

class Eye {
	constructor(x, y, w) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.init();
		this.isOpening = true;
		this.eyeSize1 = this.w * 0.4;
		this.eyeSize2 = this.w * 0.22;
		this.clr1 = '#ffffff';
		this.clr2 = '#000000';
		this.arcA = 0;
		if (this.isOpening == false) {
			this.arcA = PI;
		}
		this.pupilOffset = (this.eyeSize1 - this.eyeSize2) / 2;
		this.eyePos1 = createVector(-this.pupilOffset, 0);
		this.eyePos2 = createVector(this.pupilOffset, 0);
	}

	show() {
		push();
		translate(this.x, this.y);

		strokeWeight(width / 900);
		if ((this.arcA < PI * 0.99)) {

			push();
			fill(this.clr1);
			stroke(this.clr2);
			arc((this.w / 4), 0, this.eyeSize1, this.eyeSize1, this.arcA - PI / 2, TAU - this.arcA - PI / 2, CHORD);
			ctx.clip();
			noStroke();
			fill(this.clr2);
			circle((this.w / 4) + this.eyePos1.x, this.eyePos1.y, this.eyeSize2);
			pop();

			fill(this.clr1);
			stroke(this.clr2);
			arc(-(this.w / 4), 0, this.eyeSize1, this.eyeSize1, this.arcA - PI / 2, TAU - this.arcA - PI / 2, CHORD);
			ctx.clip();
			noStroke();
			fill(this.clr2);
			circle(-(this.w / 4) + this.eyePos2.x, this.eyePos2.y, this.eyeSize2);
		}
		pop();
	}

	move() {
		if (0 < this.progress && this.progress < this.actionTime) {
			let n = norm(this.progress, 0, this.actionTime - 1);
			if (this.actionType == 5) {
				if (this.isOpening) {
					this.arcA = lerp(0, PI, n);
				} else {
					this.arcA = lerp(PI, 0, n);
				}
			} else {
				if (this.isOpening) {
					this.arcA = lerp(0, PI, sin(easeOutQuart(n) * PI));
				}
			}
			if (this.arcA >= PI * 0.99) {
				let x1 = -this.pupilOffset;
				let y1 = 0;
				let x2 = this.pupilOffset;
				let y2 = 0;
				if (this.actionType == 1) {
					x1 = this.pupilOffset;
				} else if (this.actionType == 2) {
					x2 = -this.pupilOffset;
				}
				else if (this.actionType == 3) {
					y1 = -this.pupilOffset * 0.65;
					y2 = -this.pupilOffset * 0.65;
				}
				else if (this.actionType == 4) {
					y1 = this.pupilOffset * 0.65;
					y2 = this.pupilOffset * 0.65;
				}
				this.eyePos1 = createVector(x1, y1);
				this.eyePos2 = createVector(x2, y2);
			}
		}
		this.progress++;
		if (this.progress > this.actionTime) {
			if (this.actionType == 5) {
				if (this.isOpening) {
					this.isOpening = false;
				} else {
					this.isOpening = true;
				}
			}
			this.init();
		}
	}

	init() {
		this.actionType = int(random(5));
		this.progress = -int(random(300));
		this.actionTime = 40;
		if (this.actionType == 5) {
			this.actionTime = 20
		}
	}

	run() {
		this.move();
		this.show();
	}
}

